const enc=new TextEncoder();
const hex=a=>Array.from(new Uint8Array(a),b=>b.toString(16).padStart(2,'0')).join('');
const random=n=>hex(crypto.getRandomValues(new Uint8Array(n)));
const digest=async text=>hex(await crypto.subtle.digest('SHA-256',enc.encode(text)));
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:100000,hash:'SHA-256'},key,256))}
function same(a,b){let mismatch=a.length^b.length;for(let i=0;i<a.length;i++)mismatch|=a.charCodeAt(i)^b.charCodeAt(i);return mismatch===0}
function field(data,key,max=200){if(typeof data[key]!=='string'||!data[key].trim()||data[key].length>max)throw Object.assign(Error(`ÐŸÑ€Ð¾Ð²ÐµÑ€ÑŒÑ‚Ðµ Ð¿Ð¾Ð»Ðµ ${key}`),{status:400});return data[key].trim()}
const reply=(status,data,cookie)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...(cookie?{'Set-Cookie':cookie}:{})}});
async function api(req,env){try{const db=env.DB;if(!db)return reply(503,{error:'Ð‘Ð°Ð·Ð° Ð´Ð°Ð½Ð½Ñ‹Ñ… Ð²Ñ€ÐµÐ¼ÐµÐ½Ð½Ð¾ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°'});const path=new URL(req.url).pathname.slice(5);const token=req.headers.get('Cookie')?.match(/(?:^|;\s*)session=([a-f0-9]{64})(?:;|$)/)?.[1];const account=token?await db.prepare('SELECT u.id,u.name,u.email FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>?').bind(await digest(token),Date.now()).first():null;
if(req.method==='POST'){const origin=req.headers.get('Origin');if(origin&&new URL(origin).origin!==new URL(req.url).origin)return reply(403,{error:'Ð—Ð°Ð¿Ñ€Ð¾Ñ Ñ Ð´Ñ€ÑƒÐ³Ð¾Ð³Ð¾ ÑÐ°Ð¹Ñ‚Ð° Ð·Ð°Ð¿Ñ€ÐµÑ‰Ñ‘Ð½'});if(!req.headers.get('Content-Type')?.startsWith('application/json'))return reply(415,{error:'ÐžÐ¶Ð¸Ð´Ð°ÐµÑ‚ÑÑ JSON'})}
if(path==='me'&&req.method==='GET')return reply(200,{user:account});
if(path==='logout'&&req.method==='POST'){if(token)await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await digest(token)).run();return reply(200,{ok:true},'session=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0')}
let data;if(req.method==='POST'){const text=await req.text();if(enc.encode(text).length>16384)return reply(413,{error:'Ð¡Ð»Ð¸ÑˆÐºÐ¾Ð¼ Ð±Ð¾Ð»ÑŒÑˆÐ¾Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ'});try{data=JSON.parse(text)}catch{return reply(400,{error:'ÐÐµÐºÐ¾Ñ€Ñ€ÐµÐºÑ‚Ð½Ñ‹Ð¹ JSON'})}}
if((path==='register'||path==='login')&&req.method==='POST'){
const ip=req.headers.get('CF-Connecting-IP')||'unknown';const limitKey=await digest(ip+':'+Math.floor(Date.now()/60000));await db.prepare('INSERT INTO auth_limits(key,count,expires_at) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1').bind(limitKey,Date.now()+120000).run();const attempts=await db.prepare('SELECT count FROM auth_limits WHERE key=?').bind(limitKey).first();if(attempts.count>15)return reply(429,{error:'Ð¡Ð»Ð¸ÑˆÐºÐ¾Ð¼ Ð¼Ð½Ð¾Ð³Ð¾ Ð¿Ð¾Ð¿Ñ‹Ñ‚Ð¾Ðº. ÐŸÐ¾Ð²Ñ‚Ð¾Ñ€Ð¸Ñ‚Ðµ Ñ‡ÐµÑ€ÐµÐ· Ð¼Ð¸Ð½ÑƒÑ‚Ñƒ.'});
const email=field(data,'email',254).toLowerCase(),password=field(data,'password',128);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return reply(400,{error:'ÐÐµÐºÐ¾Ñ€Ñ€ÐµÐºÑ‚Ð½Ñ‹Ð¹ email'});if(password.length<8)return reply(400,{error:'ÐŸÐ°Ñ€Ð¾Ð»ÑŒ Ð´Ð¾Ð»Ð¶ÐµÐ½ ÑÐ¾Ð´ÐµÑ€Ð¶Ð°Ñ‚ÑŒ Ð½Ðµ Ð¼ÐµÐ½ÐµÐµ 8 ÑÐ¸Ð¼Ð²Ð¾Ð»Ð¾Ð²'});let user;
if(path==='register'){const name=field(data,'name',80);const salt=random(16);const hash=salt+':'+await passwordHash(password,salt);try{user=await db.prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?) RETURNING id,name,email').bind(name,email,hash).first()}catch(error){if(await db.prepare('SELECT id FROM users WHERE email=?').bind(email).first())return reply(409,{error:'Ð­Ñ‚Ð¾Ñ‚ email ÑƒÐ¶Ðµ Ð·Ð°Ñ€ÐµÐ³Ð¸ÑÑ‚Ñ€Ð¸Ñ€Ð¾Ð²Ð°Ð½'});throw error}}
else{const found=await db.prepare('SELECT * FROM users WHERE email=?').bind(email).first();const [salt,hash]=(found?.password_hash||'0'.repeat(32)+':'+ '0'.repeat(64)).split(':');if(!same(await passwordHash(password,salt),hash)||!found)return reply(401,{error:'ÐÐµÐ²ÐµÑ€Ð½Ñ‹Ð¹ email Ð¸Ð»Ð¸ Ð¿Ð°Ñ€Ð¾Ð»ÑŒ'});user={id:found.id,name:found.name,email:found.email}}
const newToken=random(32);await db.batch([db.prepare('DELETE FROM sessions WHERE expires_at<?').bind(Date.now()),db.prepare('DELETE FROM auth_limits WHERE expires_at<?').bind(Date.now()),db.prepare('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').bind(await digest(newToken),user.id,Date.now()+7*86400000)]);return reply(path==='register'?201:200,{user},`session=${newToken}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=604800`)}
if(path==='requests'){if(!account)return reply(401,{error:'Ð’Ð¾Ð¹Ð´Ð¸Ñ‚Ðµ Ð² Ð°ÐºÐºÐ°ÑƒÐ½Ñ‚'});if(req.method==='GET'){const rows=await db.prepare('SELECT id,model,budget,status,created_at FROM requests WHERE user_id=? ORDER BY id DESC').bind(account.id).all();return reply(200,{requests:rows.results})}if(req.method==='POST'){const name=field(data,'name',80),phone=field(data,'phone',40),email=field(data,'email',254),budget=field(data,'budget',80),model=field(data,'model',120);if(!/^[+\d\s()\-]{7,40}$/.test(phone))return reply(400,{error:'ÐŸÑ€Ð¾Ð²ÐµÑ€ÑŒÑ‚Ðµ Ð½Ð¾Ð¼ÐµÑ€ Ñ‚ÐµÐ»ÐµÑ„Ð¾Ð½Ð°'});if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return reply(400,{error:'ÐŸÑ€Ð¾Ð²ÐµÑ€ÑŒÑ‚Ðµ email'});if(data.comment!==undefined&&(typeof data.comment!=='string'||data.comment.length>3000))return reply(400,{error:'ÐšÐ¾Ð¼Ð¼ÐµÐ½Ñ‚Ð°Ñ€Ð¸Ð¹ ÑÐ»Ð¸ÑˆÐºÐ¾Ð¼ Ð´Ð»Ð¸Ð½Ð½Ñ‹Ð¹'});const result=await db.prepare('INSERT INTO requests(user_id,name,phone,email,budget,model,comment) VALUES(?,?,?,?,?,?,?) RETURNING id').bind(account.id,name,phone,email,budget,model,data.comment||'').first();return reply(201,{id:result.id})}}
return reply(404,{error:'ÐÐµ Ð½Ð°Ð¹Ð´ÐµÐ½Ð¾'})}catch(error){return reply(error.status||500,{error:error.status?error.message:'ÐžÑˆÐ¸Ð±ÐºÐ° ÑÐµÑ€Ð²ÐµÑ€Ð°'})}}

